using Godot;
using System;
using System.Linq;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;

public partial class WorldUiOperations
{
    public void set_district(Control owner,string id,int settlement,int district,string field,Variant value)
    {ModifyEntry(owner,id,"settlements",settlement,next=>{var values=Get(next,"districts",new GArray()).AsGodotArray();if(district>=0&&district<values.Count)values[district].AsGodotDictionary()[field]=value;},"Edit district "+field);}
    public void block(Control owner,string id,int settlement,string blockId,string field,Variant value)
    {
        ModifyEntry(owner,id,"settlements",settlement,next=>{if(!next.ContainsKey("block_overrides"))next["block_overrides"]=new Settings();var overrides=next["block_overrides"].AsGodotDictionary();if(!overrides.ContainsKey(blockId))overrides[blockId]=new Settings();var settings=overrides[blockId].AsGodotDictionary();if(value.VariantType==Variant.Type.Nil)settings.Remove(field);else settings[field]=value;if(settings.Count==0)overrides.Remove(blockId);},"Edit city block");
    }
    public void districts(Control owner,string id,Resource source,Node parent,Settings presets,string[] categories)
    {
        var settlements=source.Get("settlements").AsGodotArray();if(settlements.Count==0){parent.AddChild(new Label {Text="Add a settlement to edit districts and blocks.",AutowrapMode=TextServer.AutowrapMode.WordSmart});return;}int at=Math.Clamp(owner.GetMeta("world_settlement_index",0).AsInt32(),0,settlements.Count-1);Choice(owner,parent,settlements.Select(value=>value.AsGodotDictionary()["name"].AsString()).ToArray(),at,index=>{owner.SetMeta("world_settlement_index",index);owner.SetMeta("world_district_index",0);owner.Call("_refresh_properties");});var settlement=settlements[at].AsGodotDictionary();var values=Get(settlement,"districts",new GArray()).AsGodotArray();var add=new MenuButton {Text="＋ District",Disabled=values.Count>=32};parent.AddChild(add);foreach(string category in categories)add.GetPopup().AddItem(category);
        add.GetPopup().IdPressed+=index=>{if(!Fresh(add,owner))return;Modify(owner,id,next=>{var entries=next.Get("settlements").AsGodotArray();if(at>=entries.Count)return;var current=entries[at].AsGodotDictionary();var center=current["center"].AsVector3();double radius=current["radius"].AsDouble()*.6;var polygon=new[]{new Vector2((float)(center.X-radius),(float)(center.Z-radius)),new Vector2((float)(center.X+radius),(float)(center.Z-radius)),new Vector2((float)(center.X+radius),(float)(center.Z+radius)),new Vector2((float)(center.X-radius),(float)(center.Z+radius))};if(!current.ContainsKey("districts"))current["districts"]=new GArray();var district=new WorldDistrictOperations().create(categories[index],polygon,presets);district["seed"]=next.Get("seed");var districts=current["districts"].AsGodotArray();districts.Add(district);owner.SetMeta("world_district_index",districts.Count-1);},"Add city district");};
        if(values.Count>0)
        {
            int index=Math.Clamp(owner.GetMeta("world_district_index",0).AsInt32(),0,values.Count-1);Choice(owner,parent,values.Select(value=>value.AsGodotDictionary()["name"].AsString()).ToArray(),index,next=>{owner.SetMeta("world_district_index",next);owner.Call("_refresh_properties");});var district=values[index].AsGodotDictionary();var canvas=Canvas(owner);canvas.SetMeta("world_district_selection",new Settings {["world"]=id,["district"]=district["id"]});canvas.Get("overlay").As<CanvasItem>().QueueRedraw();var name=new LineEdit {Text=district["name"].AsString(),PlaceholderText="District name"};parent.AddChild(name);name.TextSubmitted+=text=>{if(Fresh(name,owner))set_district(owner,id,at,index,"name",text);};
            Button(owner,parent,"✎ Edit district boundary",()=>{var current=Canvas(owner);current.Set("environment_tool","District boundary");current.GrabFocus();current.Get("overlay").As<CanvasItem>().QueueRedraw();}).TooltipText="Drag points to move them. Click an edge to insert a point; right-click a point to remove it. Escape cancels a drag.";Toggle(owner,parent,"District enabled",Get(district,"enabled",true).AsBool(),on=>set_district(owner,id,at,index,"enabled",on));
            Choice(owner,parent,categories,Array.IndexOf(categories,district["category"].AsString()),choice=>ModifyEntry(owner,id,"settlements",at,next=>{var entries=Get(next,"districts",new GArray()).AsGodotArray();if(index>=entries.Count)return;var previous=entries[index].AsGodotDictionary();var replacement=new WorldDistrictOperations().create(categories[choice],previous["polygon"].AsVector2Array(),presets);replacement["id"]=previous["id"];replacement["name"]=previous["name"];entries[index]=replacement;},"Change district preset"));
            foreach(var spec in new[]{("Building density","density",0.0,1.0,.05),("Minimum floors","height_min",1.0,8.0,1.0),("Maximum floors","height_max",1.0,8.0,1.0),("Lot size","lot_size",10.0,64.0,1.0),("Setback","setback",0.0,10.0,.25)})Value(owner,parent,spec.Item1,Get(district,spec.Item2,spec.Item3).AsDouble(),spec.Item3,spec.Item4,spec.Item5,value=>set_district(owner,id,at,index,spec.Item2,value));
            var styles=presets.Keys.Select(key=>key.AsString()).ToArray();Choice(owner,parent,styles,Math.Max(0,Array.IndexOf(styles,district["template"].As<Resource>().Get("style").AsString())),choice=>ModifyEntry(owner,id,"settlements",at,next=>{var entries=Get(next,"districts",new GArray()).AsGodotArray();if(index>=entries.Count)return;var current=entries[index].AsGodotDictionary();var styled=new BuildingStyleOperations().apply(current["template"].As<Resource>(),styles[choice],presets);current["template"]=styled!=null?Variant.From(styled):default;},"Change district architecture"));Button(owner,parent,"⟳ Vary district",()=>set_district(owner,id,at,index,"seed",Get(district,"seed",1).AsInt64()+1));
            Button(owner,parent,"Remove district",()=>ModifyEntry(owner,id,"settlements",at,next=>{var entries=Get(next,"districts",new GArray()).AsGodotArray();if(index>=entries.Count)return;entries.RemoveAt(index);foreach(var value in Get(next,"block_overrides",new Settings()).AsGodotDictionary().Values){var settings=value.AsGodotDictionary();if(Get(settings,"district_id","").AsString()==district["id"].AsString())settings.Remove("district_id");}},"Remove city district"));
        }
        parent.AddChild(new Label {Text="BLOCK OVERRIDES"});var root=Session(owner).Get("document").As<Resource>().Call("component",id).As<Resource>();if(root==null)return;var blocks=Get(root.Get("parameters").AsGodotDictionary(),"world_blocks",new GArray()).AsGodotArray().Select(value=>value.AsGodotDictionary()).Where(value=>value["settlement"].AsString()==settlement["id"].AsString()).ToArray();if(blocks.Length==0)return;int selected=Math.Clamp(owner.GetMeta("world_block_index",0).AsInt32(),0,blocks.Length-1);Choice(owner,parent,blocks.Select((value,index)=>"Block "+(index+1)+" · "+value["district"].AsString()).ToArray(),selected,next=>{owner.SetMeta("world_block_index",next);owner.Call("_refresh_properties");});string blockId=blocks[selected]["id"].AsString();var settingsOverride=Get(Get(settlement,"block_overrides",new Settings()).AsGodotDictionary(),blockId,new Settings()).AsGodotDictionary();var labels=new[]{"District from boundary"}.Concat(values.Select(value=>value.AsGodotDictionary()["name"].AsString())).ToArray();int assigned=0;for(int index=0;index<values.Count;index++)if(Get(settingsOverride,"district_id","").AsString()==values[index].AsGodotDictionary()["id"].AsString())assigned=index+1;Choice(owner,parent,labels,assigned,next=>block(owner,id,at,blockId,"district_id",next==0?default:values[next-1].AsGodotDictionary()["id"]));Toggle(owner,parent,"Keep this block open",settingsOverride.ContainsKey("density")&&settingsOverride["density"].AsDouble()==0,on=>block(owner,id,at,blockId,"density",on?Variant.From(0.0):default));Button(owner,parent,"↶ Reset block overrides",()=>ModifyEntry(owner,id,"settlements",at,next=>Get(next,"block_overrides",new Settings()).AsGodotDictionary().Remove(blockId),"Reset block overrides")).Disabled=settingsOverride.Count==0;
    }
}
